import{_ as e,o as a,c as d,a2 as n}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"GenAIOps -- enumerated source for the GenAIOps Maturity Model Assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/genaiops-maturity-question-set.md","filePath":"frameworks/genaiops-maturity-question-set.md"}'),r={name:"frameworks/genaiops-maturity-question-set.md"};function o(s,t,i,l,m,c){return a(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="genaiops-enumerated-source-for-the-genaiops-maturity-model-assessment" tabindex="-1">GenAIOps -- enumerated source for the GenAIOps Maturity Model Assessment <a class="header-anchor" href="#genaiops-enumerated-source-for-the-genaiops-maturity-model-assessment" aria-label="Permalink to &quot;GenAIOps -- enumerated source for the GenAIOps Maturity Model Assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below -- read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>genaiops.maturity.yaml</code> scores the review in Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/e14e1e9f-d339-4d7e-b2bb-24f056cf08b6/" target="_blank" rel="noreferrer">GenAIOps Maturity Model Assessment</a>, a questionnaire that places an organisation on a four-level maturity model for Generative Artificial Intelligence Operations (GenAIOps, sometimes called LLMOps): initial, defined, managed and optimized. <code>src/assess/rules/genaiops.maturity.yaml</code> is written against this page only, and every rule cites an item number from the tables below. The maturity ladders are <strong>manual</strong> questions answered with <code>-AssessmentAnswers</code>; two supporting checks that Azure data can answer are <strong>automated</strong>.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/e14e1e9f-d339-4d7e-b2bb-24f056cf08b6/" target="_blank" rel="noreferrer">GenAIOps Maturity Model Assessment</a> (question text and points not published)</td></tr><tr><td>Framework version</td><td>GenAIOps maturity model guidance (four levels, score bands initial 0-9, maturing 10-14 and 15-19, optimized 20-28) on Microsoft Learn, current as of the extraction date</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The maturity guidance page and the GenAIOps-for-MLOps page were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Every property an automated item reads was checked against the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions and points are not published. The items below are <strong>Scout-derived</strong>: for each of seven dimensions Scout writes four statements, one per maturity level, from that level&#39;s description in Microsoft&#39;s maturity guidance and from the operating practices in the GenAIOps guidance (prompt and data versioning, experimentation and evaluation, deployment automation, monitoring, content safety and resource management). The <code>GENAIOPS-*</code> IDs, the dimension names and the level each statement is assigned to are Scout&#39;s own judgement. Scout reports the share of statements met per dimension. It does not reproduce Microsoft&#39;s 0-28 points and does not place the organisation on a level.</p><p>Sources:</p><ul><li>[MAT] <a href="https://learn.microsoft.com/azure/machine-learning/prompt-flow/concept-llmops-maturity" target="_blank" rel="noreferrer">Advance your maturity level for Generative Artificial Intelligence Operations (GenAIOps)</a></li><li>[GAO] <a href="https://learn.microsoft.com/azure/architecture/ai-ml/guide/genaiops-for-mlops" target="_blank" rel="noreferrer">Generative AI operations for organizations with MLOps investments</a></li><li>[WAFO] <a href="https://learn.microsoft.com/azure/well-architected/ai/mlops-genaiops" target="_blank" rel="noreferrer">MLOps and GenAIOps for AI workloads on Azure</a></li><li>[SEC] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/secure" target="_blank" rel="noreferrer">Guidance to set up your organization&#39;s AI security process</a></li></ul><p>Automated items are <strong>gated</strong>: they run only when the resources they judge exist, so an estate without them reports those items Not assessed rather than passed or failed. Manual items are answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>); where collected Azure data bears on the question it is attached to the item as evidence.</p><h2 id="the-enumeration-30-items-across-7-dimensions" tabindex="-1">The enumeration -- 30 items across 7 dimensions <a class="header-anchor" href="#the-enumeration-30-items-across-7-dimensions" aria-label="Permalink to &quot;The enumeration -- 30 items across 7 dimensions&quot;">​</a></h2><h3 id="prompt-design-and-orchestration-pd-4-items" tabindex="-1">Prompt design and orchestration (PD) -- 4 items <a class="header-anchor" href="#prompt-design-and-orchestration-pd-4-items" aria-label="Permalink to &quot;Prompt design and orchestration (PD) -- 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-PD-01</td><td>Prompts are designed deliberately, with a system message and structure, not ad hoc</td><td>Manual</td><td>MAT; level 1 (initial)</td></tr><tr><td>GENAIOPS-PD-02</td><td>More complex prompts are integrated into applications through an orchestration layer</td><td>Manual</td><td>MAT, GAO; level 2 (defined)</td></tr><tr><td>GENAIOPS-PD-03</td><td>Prompts, orchestration and models are optimised for specific requirements</td><td>Manual</td><td>MAT, GAO; level 3 (managed)</td></tr><tr><td>GENAIOPS-PD-04</td><td>The prompt and model strategy is revisited as large language models evolve</td><td>Manual</td><td>MAT; level 4 (optimized)</td></tr></tbody></table><h3 id="asset-management-and-versioning-am-4-items" tabindex="-1">Asset management and versioning (AM) -- 4 items <a class="header-anchor" href="#asset-management-and-versioning-am-4-items" aria-label="Permalink to &quot;Asset management and versioning (AM) -- 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-AM-01</td><td>Prompts and configuration are kept in a shared, known place</td><td>Manual</td><td>MAT; level 1 (initial)</td></tr><tr><td>GENAIOPS-AM-02</td><td>Prompts, datasets, indexes and orchestration code are under source control</td><td>Manual</td><td>MAT, GAO; level 2 (defined)</td></tr><tr><td>GENAIOPS-AM-03</td><td>Advanced version control and rollback exist for prompts, models, indexes and orchestration</td><td>Manual</td><td>MAT, GAO; level 3 (managed)</td></tr><tr><td>GENAIOPS-AM-04</td><td>A model and prompt catalogue is maintained and retirement dates are tracked</td><td>Manual</td><td>MAT, WAFO; level 4 (optimized)</td></tr></tbody></table><h3 id="evaluation-and-experimentation-ev-4-items" tabindex="-1">Evaluation and experimentation (EV) -- 4 items <a class="header-anchor" href="#evaluation-and-experimentation-ev-4-items" aria-label="Permalink to &quot;Evaluation and experimentation (EV) -- 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-EV-01</td><td>Basic metrics evaluate application performance</td><td>Manual</td><td>MAT; level 1 (initial)</td></tr><tr><td>GENAIOPS-EV-02</td><td>Evaluation uses groundedness, relevance and similarity</td><td>Manual</td><td>MAT, GAO; level 2 (defined)</td></tr><tr><td>GENAIOPS-EV-03</td><td>Evaluations run automatically on every change, against agreed thresholds</td><td>Manual</td><td>MAT, GAO; level 3 (managed)</td></tr><tr><td>GENAIOPS-EV-04</td><td>Evaluation continues in production with sampled traffic and human feedback</td><td>Manual</td><td>MAT, GAO; level 4 (optimized)</td></tr></tbody></table><h3 id="deployment-dp-4-items" tabindex="-1">Deployment (DP) -- 4 items <a class="header-anchor" href="#deployment-dp-4-items" aria-label="Permalink to &quot;Deployment (DP) -- 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-DP-01</td><td>There is a repeatable way to deploy the generative AI application</td><td>Manual</td><td>MAT; level 1 (initial)</td></tr><tr><td>GENAIOPS-DP-02</td><td>Deployment is systematic and integrated with CI/CD</td><td>Manual -- <code>management.deployments</code> attached as evidence</td><td>MAT, WAFO; level 2 (defined)</td></tr><tr><td>GENAIOPS-DP-03</td><td>Structured deployment uses progressive exposure and side-by-side versions</td><td>Manual</td><td>MAT, GAO; level 3 (managed)</td></tr><tr><td>GENAIOPS-DP-04</td><td>The pipeline automates build, evaluation, promotion and rollback end to end</td><td>Manual</td><td>MAT, WAFO; level 4 (optimized)</td></tr></tbody></table><h3 id="monitoring-and-feedback-mn-4-items" tabindex="-1">Monitoring and feedback (MN) -- 4 items <a class="header-anchor" href="#monitoring-and-feedback-mn-4-items" aria-label="Permalink to &quot;Monitoring and feedback (MN) -- 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-MN-01</td><td>Basic operational metrics are collected</td><td>Manual -- <code>opsPosture.diagnosticCoverage</code> attached as evidence</td><td>MAT; level 1 (initial)</td></tr><tr><td>GENAIOPS-MN-02</td><td>Token usage, latency and throttling are monitored with alerts</td><td>Manual -- <code>monitor.metricAlertRules</code> attached as evidence</td><td>MAT, GAO; level 2 (defined)</td></tr><tr><td>GENAIOPS-MN-03</td><td>Monitoring is proactive, with drift detection and user feedback</td><td>Manual</td><td>MAT, GAO; level 3 (managed)</td></tr><tr><td>GENAIOPS-MN-04</td><td>Production learnings feed back into evaluation and improvement automatically</td><td>Manual</td><td>MAT, WAFO; level 4 (optimized)</td></tr></tbody></table><h3 id="content-safety-and-responsible-ai-cs-5-items" tabindex="-1">Content safety and responsible AI (CS) -- 5 items <a class="header-anchor" href="#content-safety-and-responsible-ai-cs-5-items" aria-label="Permalink to &quot;Content safety and responsible AI (CS) -- 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-CS-01</td><td>Responsible AI and basic content filtering are considered</td><td>Manual</td><td>MAT; level 1 (initial)</td></tr><tr><td>GENAIOPS-CS-02</td><td>Content safety is configured and ethical considerations are reviewed</td><td>Manual</td><td>MAT, GAO; level 2 (defined)</td></tr><tr><td>GENAIOPS-CS-03</td><td>Content safety is comprehensive, covering prompts and completions</td><td>Manual</td><td>MAT, GAO; level 3 (managed)</td></tr><tr><td>GENAIOPS-CS-04</td><td>Safety is evaluated continuously and reported</td><td>Manual</td><td>MAT; level 4 (optimized)</td></tr><tr><td>GENAIOPS-CS-05</td><td>Defender for Cloud threat protection for AI services is enabled</td><td>Automated -- <code>security.defenderPlans</code></td><td>GAO, SEC</td></tr></tbody></table><h3 id="resource-and-cost-management-rm-5-items" tabindex="-1">Resource and cost management (RM) -- 5 items <a class="header-anchor" href="#resource-and-cost-management-rm-5-items" aria-label="Permalink to &quot;Resource and cost management (RM) -- 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAIOPS-RM-01</td><td>Model quotas and token usage are understood</td><td>Manual</td><td>MAT, GAO; level 1 (initial)</td></tr><tr><td>GENAIOPS-RM-02</td><td>Usage is tracked per application with budgets</td><td>Manual</td><td>MAT, GAO; level 2 (defined)</td></tr><tr><td>GENAIOPS-RM-03</td><td>Capacity and cost are optimised per workload</td><td>Manual</td><td>MAT, WAFO; level 3 (managed)</td></tr><tr><td>GENAIOPS-RM-04</td><td>Cost and capacity are forecast and governed centrally</td><td>Manual</td><td>MAT, WAFO; level 4 (optimized)</td></tr><tr><td>GENAIOPS-RM-05</td><td>Azure budgets are set</td><td>Automated -- <code>governance.budgets</code></td><td>GAO</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Prompt design and orchestration</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Asset management and versioning</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Evaluation and experimentation</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Deployment</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Monitoring and feedback</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Content safety and responsible AI</td><td>5</td><td>1</td><td>4</td></tr><tr><td>Resource and cost management</td><td>5</td><td>1</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>30</strong></td><td><strong>2</strong></td><td><strong>28</strong></td></tr></tbody></table><p>Answer each statement independently. A statement marked with a higher level can be met while a lower one is not (for example automated promotion without a documented procedure), and the report shows that unevenness rather than hiding it. <code>GENAIOPS-CS-05</code> and <code>GENAIOPS-RM-05</code> are supporting checks outside the four-level ladders.</p>',28)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
